func (s *Server) evidenceRead(ctx context.Context, _ *mcp.CallToolRequest, input EvidenceReadInput) (*mcp.CallToolResult, EvidenceReadOutput, error) {
	value, err := s.service.ReadEvidence(ctx, input.ID)
	if err != nil {
		return nil, EvidenceReadOutput{}, err
	}
	result := candidateEvidenceRead{Evidence: value}
	if value.StartRune <= 0 && input.SourceContextLimit <= 0 {
		return nil, EvidenceReadOutput{Evidence: result}, nil
	}
	source, err := s.service.Read(ctx, value.SourceID)
	if err != nil {
		return nil, EvidenceReadOutput{}, err
	}
	if source.ID != value.SourceID || source.Revision != value.SourceRevision {
		return nil, EvidenceReadOutput{}, errors.New("证据来源版本已经变化")
	}
	sourceRunes := utf8.RuneCountInString(source.Content)
	if input.SourceContextLimit > 0 && sourceRunes <= input.SourceContextLimit {
		result.SourceCompleteEndRune = sourceRunes
		result.SourceComplete = source.Content
		return nil, EvidenceReadOutput{Evidence: result}, nil
	}
	if value.StartRune > 0 {
		endRune := min(128, value.StartRune)
		endByte := 0
		for count := 0; count < endRune && endByte < len(source.Content); count++ {
			_, size := utf8.DecodeRuneInString(source.Content[endByte:])
			if size <= 0 {
				return nil, EvidenceReadOutput{}, errors.New("证据来源首部不是有效 UTF-8")
			}
			endByte += size
		}
		if endRune <= 0 || endByte <= 0 || endByte > len(source.Content) {
			return nil, EvidenceReadOutput{}, errors.New("证据来源首部区间无效")
		}
		result.SourcePreludeEndRune = endRune
		result.SourcePrelude = source.Content[:endByte]
	}
	return nil, EvidenceReadOutput{Evidence: result}, nil
}

