func (s *Server) evidenceSearch(ctx context.Context, _ *mcp.CallToolRequest, input EvidenceSearchInput) (*mcp.CallToolResult, EvidenceSearchOutput, error) {
	limit := input.Limit
	if limit == 0 {
		limit = 3
	}
	probeLimit := min(limit+1, 8)
	values, err := s.service.SearchEvidence(ctx, contract.EvidenceSearchInput{SourceID: input.SourceID, Query: input.Query, Limit: probeLimit})
	if err != nil {
		return nil, EvidenceSearchOutput{}, err
	}
	truncated := len(values) > limit
	if truncated {
		values = values[:limit]
	}
	result := EvidenceSearchOutput{Evidence: values, Truncated: truncated}
	if truncated {
		source, err := s.service.Read(ctx, input.SourceID)
		if err != nil {
			return nil, EvidenceSearchOutput{}, err
		}
		for _, reference := range values {
			if reference.SourceID != source.ID || reference.SourceRevision != source.Revision {
				return nil, EvidenceSearchOutput{}, errors.New("证据搜索来源版本已经变化")
			}
		}
		result.SourceRunes = utf8.RuneCountInString(source.Content)
	}
	return nil, result, nil
}
